import * as fs from 'node:fs';
import { describe, expect, test } from 'vitest';
import { toJsonString } from '@bufbuild/protobuf';
import { RouterConfigSchema } from '@wundergraph/cosmo-connect/dist/node/v1/node_pb';
import { buildRouterConfigWithoutContexts } from './testdata/without-contexts';

describe('Router config without contextual arguments', () => {
  // The fixture was generated by the builder of main, so it must not be regenerated from this code.
  test('that the router config is identical to the fixture byte for byte', () => {
    expect(toJsonString(RouterConfigSchema, buildRouterConfigWithoutContexts())).toBe(
      fs.readFileSync('test/testdata/router-config-without-contexts.json').toString(),
    );
  });
});
